; Epoch sound driver -- Dragon Slayer I (J)
; ROM bank $01, $7038-$7FFD. Assembles byte-identical with RGBDS 1.0.
; Generated by tools/epoch_gen.py. No macros: data is plain db/dw with a
; comment on each row. See Epoch_SoundDriver.md for the format.

INCLUDE "epoch_sound.inc"

DEF SND_RAM EQU $D100
DEF TRK_SIZE EQU $20

; driver RAM
DEF wSndMusicId       EQU $D100
DEF wSndSfxId         EQU $D101
DEF wSndMusicTracks   EQU $D102
DEF wSndSfxTracks     EQU $D103
DEF wSndMusicTempo    EQU $D104
DEF wSndSfxTempo      EQU $D105
DEF wSndPan           EQU $D106
DEF wSndPanFlag       EQU $D107
DEF wSndTrackIndex    EQU $D108
DEF wSndRowByte       EQU $D1C9
DEF wSndMusicLengths  EQU $D1D1
DEF wSndSfxLengths    EQU $D1D3
DEF wSndCh1           EQU $D109  ; music track struct
DEF wSndCh2           EQU $D129  ; music track struct
DEF wSndCh3           EQU $D149  ; music track struct
DEF wSndCh4           EQU $D169  ; music track struct
DEF wSndSfxCh1        EQU $D189  ; SFX track struct
DEF wSndSfxCh4        EQU $D1A9  ; SFX track struct

SECTION "Epoch sound", ROMX[$7038], BANK[$1]


; Entry points (jump table at the start of the driver).
; The game calls Sound_Output, then Sound_Update, once per frame.
Sound_Update::
    jp SndUpdate                            ; $7038  once per frame, after SndOutput
Sound_Output::
    jp SndOutput                            ; $703B  once per frame
Sound_Init::
    jp SndInit                              ; $703E  boot
Sound_PlayMusic::
    jp SndPlayMusic                         ; $7041  a = music id
Sound_PlaySfx::
    jp SndPlaySfx                           ; $7044  a = SFX id
Sound_StopMusic::
    jp SndStopMusic                         ; $7047
Sound_StopSfx::
    jp SndStopSfx                           ; $704A

; SndInit: APU on, master volume max, all channels on both sides,
; loads the fixed wave and stops everything.
SndInit:
    ld a,$00                                ; $704D
    ldh [rNR30],a                           ; $704F
    ld a,$20                                ; $7051
    ldh [rNR32],a                           ; $7053
    ld a,$77                                ; $7055
    ldh [rNR50],a                           ; $7057
    ld a,$FF                                ; $7059
    ldh [rNR51],a                           ; $705B
    ldh [rNR52],a                           ; $705D
    ld [wSndPan],a                          ; $705F
    call SndLoadWave                        ; $7062
    call Sound_StopMusic                    ; $7065
    jp Sound_StopSfx                        ; $7068

; Copies the 16-byte SndWave into wave RAM. This is the only wave the
; driver ever uses.
SndLoadWave:
    ld hl,SndWave                           ; $706B
    ld c,$30                                ; $706E
    ld b,$10                                ; $7070
.l7072
    ld a,[hli]                              ; $7072
    ldh [c],a                               ; $7073
    inc c                                   ; $7074
    dec b                                   ; $7075
    jr nz,.l7072                            ; $7076
    ret                                     ; $7078

; the only wave: a fixed, roughly sine-like shape
SndWave:
    db $CE, $FE, $B8, $BE, $FF, $FF, $FE, $B9
    db $63, $10, $00, $00, $00, $00, $13, $69


; SndPlayMusic: a = music id.
; Header: tempo (1 byte), length table (word), then 4 track pointers
; (ch1, ch2, ch3, ch4). A null pointer means the channel is unused.
SndPlayMusic:
    ld [wSndMusicId],a                      ; $7089
    ld de,MusicTable                        ; $708C
    sla a                                   ; $708F
    add a,e                                 ; $7091
    ld e,a                                  ; $7092
    ld a,d                                  ; $7093
    adc a,$00                               ; $7094
    ld d,a                                  ; $7096
    ld a,[de]                               ; $7097
    ld l,a                                  ; $7098
    inc de                                  ; $7099
    ld a,[de]                               ; $709A
    ld h,a                                  ; $709B
    ld a,$00                                ; $709C
    ldh [rNR30],a                           ; $709E
    ld a,$05                                ; $70A0  dead load
    ld a,$04                                ; $70A2  active music tracks
    ld [wSndMusicTracks],a                  ; $70A4
    ld a,[hli]                              ; $70A7
    ld [wSndMusicTempo],a                   ; $70A8
    ld a,[hli]                              ; $70AB
    ld [wSndMusicLengths],a                 ; $70AC
    ld a,[hli]                              ; $70AF
    ld [wSndMusicLengths + 1],a             ; $70B0
    ld de,wSndCh1                           ; $70B3
    ld c,$04                                ; $70B6
.trackLoop
    ld a,$01                                ; $70B8  TRK_STATUS = 1
    ld [de],a                               ; $70BA
    inc de                                  ; $70BB  TRK_PTR
    ld a,[hli]                              ; $70BC
    ld [de],a                               ; $70BD
    ld b,a                                  ; $70BE
    inc de                                  ; $70BF
    ld a,[hld]                              ; $70C0  reads the high byte and steps back, so the pointer can be re-read for TRK_START
    ld [de],a                               ; $70C1
    or b                                    ; $70C2
    jr z,.noTrack                           ; $70C3
    inc e                                   ; $70C5  TRK_COUNT = 0
    ld a,$00                                ; $70C6
    ld [de],a                               ; $70C8
    inc e                                   ; $70C9
    ld [de],a                               ; $70CA
    ld a,e                                  ; $70CB  TRK_LOOPDEPTH = 0
    add a,$0D                               ; $70CC
    ld e,a                                  ; $70CE
    ld a,$00                                ; $70CF
    ld [de],a                               ; $70D1
    ld a,e                                  ; $70D2
    add a,$0D                               ; $70D3
    ld e,a                                  ; $70D5
    ld a,[hli]                              ; $70D6  TRK_START = TRK_PTR
    ld [de],a                               ; $70D7
    inc e                                   ; $70D8
    ld a,[hli]                              ; $70D9
    ld [de],a                               ; $70DA
    inc e                                   ; $70DB
    dec c                                   ; $70DC
    jr nz,.trackLoop                        ; $70DD
    ret                                     ; $70DF
.noTrack
    inc hl                                  ; $70E0
    inc hl                                  ; $70E1
    dec e                                   ; $70E2
    dec e                                   ; $70E3
    ld a,$04                                ; $70E4  status 4: silenced and counted down by SndOutput
    ld [de],a                               ; $70E6
    ld a,e                                  ; $70E7
    add a,$20                               ; $70E8
    ld e,a                                  ; $70EA
    dec c                                   ; $70EB
    jr nz,.trackLoop                        ; $70EC
    ret                                     ; $70EE

; SndPlaySfx: a = SFX id.
; Header: tempo, length table, then 2 track pointers. The first runs on
; hardware ch1 (tone), the second on ch4 (noise).
SndPlaySfx:
    ld [wSndSfxId],a                        ; $70EF
    ld de,SfxTable                          ; $70F2
    sla a                                   ; $70F5
    add a,e                                 ; $70F7
    ld e,a                                  ; $70F8
    ld a,d                                  ; $70F9
    adc a,$00                               ; $70FA
    ld d,a                                  ; $70FC
    ld a,[de]                               ; $70FD
    ld l,a                                  ; $70FE
    inc de                                  ; $70FF
    ld a,[de]                               ; $7100
    ld h,a                                  ; $7101
    ld a,$02                                ; $7102
    ld [wSndSfxTracks],a                    ; $7104
    ld a,[hli]                              ; $7107
    ld [wSndSfxTempo],a                     ; $7108
    ld a,[hli]                              ; $710B
    ld [wSndSfxLengths],a                   ; $710C
    ld a,[hli]                              ; $710F
    ld [wSndSfxLengths + 1],a               ; $7110
    ld de,wSndSfxCh1                        ; $7113
    ld c,$02                                ; $7116
.trackLoop
    ld a,$01                                ; $7118  TRK_STATUS = 1
    ld [de],a                               ; $711A
    inc de                                  ; $711B  TRK_PTR
    ld a,[hli]                              ; $711C
    ld [de],a                               ; $711D
    ld b,a                                  ; $711E
    inc de                                  ; $711F
    ld a,[hld]                              ; $7120
    ld [de],a                               ; $7121
    or b                                    ; $7122
    jr z,.noTrack                           ; $7123
    inc de                                  ; $7125  TRK_COUNT = 0
    ld a,$00                                ; $7126
    ld [de],a                               ; $7128
    inc de                                  ; $7129
    ld [de],a                               ; $712A
    ld a,e                                  ; $712B  TRK_LOOPDEPTH = 0
    add a,$0D                               ; $712C
    ld e,a                                  ; $712E
    ld a,$00                                ; $712F
    ld [de],a                               ; $7131
    ld a,e                                  ; $7132
    add a,$0D                               ; $7133
    ld e,a                                  ; $7135
    ld a,[hli]                              ; $7136  TRK_START = TRK_PTR
    ld [de],a                               ; $7137
    inc e                                   ; $7138
    ld a,[hli]                              ; $7139
    ld [de],a                               ; $713A
    inc de                                  ; $713B
    dec c                                   ; $713C
    jr nz,.trackLoop                        ; $713D
    jr .done                                ; $713F
.noTrack
    inc hl                                  ; $7141
    inc hl                                  ; $7142
    dec e                                   ; $7143
    dec e                                   ; $7144
    ld a,$04                                ; $7145
    ld [de],a                               ; $7147
    ld a,e                                  ; $7148
    add a,$20                               ; $7149
    ld e,a                                  ; $714B
    dec c                                   ; $714C
    jr nz,.trackLoop                        ; $714D
.done
    ld a,$02                                ; $714F  2 = SFX just started (SndUpdate turns it into 1)
    ld [wSndPanFlag],a                      ; $7151
    ret                                     ; $7154

; SndStopMusic: marks all 4 music tracks "ending" (status 4). The next
; SndOutput silences them.
SndStopMusic:
    ld a,$04                                ; $7155
    ld [wSndMusicTracks],a                  ; $7157
    ld [wSndCh1],a                          ; $715A
    ld [wSndCh2],a                          ; $715D
    ld [wSndCh3],a                          ; $7160
    ld [wSndCh4],a                          ; $7163
    ret                                     ; $7166

; SndStopSfx: same for the 2 SFX tracks.
SndStopSfx:
    ld a,$02                                ; $7167
    ld [wSndSfxTracks],a                    ; $7169
    ld a,$04                                ; $716C
    ld [wSndSfxCh1],a                       ; $716E
    ld [wSndSfxCh4],a                       ; $7171
    ret                                     ; $7174

; SndUpdate: the sequencer tick. Runs the 6 tracks in order
; (music ch1-ch4, SFX ch1, SFX ch4).
; Each track: counter -= tempo. While it has not underflowed, only the
; instrument envelope runs. When it underflows, rows are parsed until
; the next note/rest/tie.
SndUpdate:
    ld a,[wSndPanFlag]                      ; $7175  2 = SFX just started
    cp $02                                  ; $7178
    jr nz,.go                               ; $717A
    ld a,$01                                ; $717C
    ld [wSndPanFlag],a                      ; $717E
.go
    ld hl,wSndCh1                           ; $7181
    ld a,$00                                ; $7184
    ld [wSndTrackIndex],a                   ; $7186

; hl = track struct
SndTrackLoop:
    push hl                                 ; $7189
    ld a,[hli]                              ; $718A
    and $03                                 ; $718B
    jp z,SndNextTrack                       ; $718D
    ld c,a                                  ; $7190
    ld a,[hli]                              ; $7191
    ld e,a                                  ; $7192
    ld a,[hli]                              ; $7193
    ld d,a                                  ; $7194
    ld a,[wSndTrackIndex]                   ; $7195
    cp $04                                  ; $7198  tracks 4/5 are SFX
    jr nc,.l71A1                            ; $719A
    ld a,[wSndMusicTempo]                   ; $719C
    jr .l71A4                               ; $719F
.l71A1
    ld a,[wSndSfxTempo]                     ; $71A1
.l71A4
    ld b,a                                  ; $71A4
    ld a,[hl]                               ; $71A5
    sub b                                   ; $71A6
    ld [hli],a                              ; $71A7
    ld a,[hl]                               ; $71A8
    sbc a,$00                               ; $71A9
    ld [hli],a                              ; $71AB
    jp nc,SndTrackEnvelope                  ; $71AC

; de = data pointer, hl = TRK_NOTE, track struct on the stack.
SndParse:
    ld a,[de]                               ; $71AF
    cp $F0                                  ; $71B0
    jp nz,SndParseRow                       ; $71B2
; $F0 nn: instrument. Ignored on noise tracks (ch4 / SFX ch4).
; Copies 5 register bytes to TRK_NR0..TRK_NR4 and the mode byte,
; then mode-specific parameters.
.instrument
    inc de                                  ; $71B5
    ld a,[de]                               ; $71B6
    inc de                                  ; $71B7
    sla a                                   ; $71B8
    push de                                 ; $71BA
    push hl                                 ; $71BB
    ld hl,InstTable                         ; $71BC
    add a,l                                 ; $71BF
    ld l,a                                  ; $71C0
    ld a,$00                                ; $71C1
    adc a,h                                 ; $71C3
    ld h,a                                  ; $71C4
    ld a,[wSndTrackIndex]                   ; $71C5
    cp $03                                  ; $71C8  noise tracks ignore instruments
    jr z,.instDone                          ; $71CA
    cp $05                                  ; $71CC
    jr z,.instDone                          ; $71CE
    ld a,[hli]                              ; $71D0
    ld e,a                                  ; $71D1
    ld a,[hl]                               ; $71D2
    ld d,a                                  ; $71D3
    pop hl                                  ; $71D4
    push hl                                 ; $71D5
    inc l                                   ; $71D6
    ld c,$05                                ; $71D7
.l71D9
    ld a,[de]                               ; $71D9
    inc de                                  ; $71DA
    ld [hli],a                              ; $71DB
    dec c                                   ; $71DC
    jr nz,.l71D9                            ; $71DD
    ld a,[de]                               ; $71DF
    ld [hli],a                              ; $71E0
    and a                                   ; $71E1
    jr z,.instDone                          ; $71E2
    ; mode 1: volume steps. TRK_ENVPARAM = TRK_ENVCOUNT = rate,
    ; TRK_ENVPTR = address of the step list, TRK_ENVINDEX = 0.
    cp $01                                  ; $71E4
    jr nz,.notMode1                         ; $71E6
    inc de                                  ; $71E8
    ld a,[de]                               ; $71E9
    ld [hli],a                              ; $71EA
    ld [hli],a                              ; $71EB
    inc de                                  ; $71EC
    ld a,e                                  ; $71ED
    ld [hli],a                              ; $71EE
    ld a,d                                  ; $71EF
    ld [hli],a                              ; $71F0
    ld a,$00                                ; $71F1
    ld [hl],a                               ; $71F3
    pop hl                                  ; $71F4
    pop de                                  ; $71F5
    jp SndParse                             ; $71F6
; mode 2: TRK_ENVPARAM = TRK_ENVCOUNT = frames (broken, see SndTrackEnvelope)
.notMode1
    cp $02                                  ; $71F9
    jr nz,.gateMode                         ; $71FB
    inc de                                  ; $71FD
    ld a,[de]                               ; $71FE
    ld [hli],a                              ; $71FF
    ld [hli],a                              ; $7200
    jr .instDone                            ; $7201
; mode 3 and up: TRK_ENVPARAM = n * current tempo (gate, in counter units).
.gateMode
    inc de                                  ; $7203
    ld a,[de]                               ; $7204
    ld c,a                                  ; $7205
    ld a,[wSndTrackIndex]                   ; $7206
    cp $04                                  ; $7209
    jr nc,.l7212                            ; $720B
    ld a,[wSndMusicTempo]                   ; $720D
    jr .l7215                               ; $7210
.l7212
    ld a,[wSndSfxTempo]                     ; $7212
.l7215
    ld b,a                                  ; $7215
    ld a,$00                                ; $7216
    ld d,a                                  ; $7218
.l7219
    add a,b                                 ; $7219
    jr nc,.l721D                            ; $721A
    inc d                                   ; $721C
.l721D
    dec c                                   ; $721D
    jr nz,.l7219                            ; $721E
    ld [hli],a                              ; $7220
    ld a,d                                  ; $7221
    ld [hl],a                               ; $7222
    jr .instDone                            ; $7223
.instDone
    pop hl                                  ; $7225
    pop de                                  ; $7226
    jp SndParse                             ; $7227

; Row byte < $E0: hi nibble = length, lo nibble = pitch.
; hi nibble 0-C: length = lengths[hi] (song length table).
; hi nibble D:   length = next 2 bytes (little-endian).
SndParseRow:
    cp $E0                                  ; $722A
    jp nc,SndParseCmd                       ; $722C
    ld [wSndRowByte],a                      ; $722F
    and $F0                                 ; $7232
    cp $D0                                  ; $7234
    jr nz,.tableLength                      ; $7236
    inc de                                  ; $7238
    ld a,[de]                               ; $7239
    ld c,a                                  ; $723A
    inc de                                  ; $723B
    ld a,[de]                               ; $723C
    ld b,a                                  ; $723D
    jr .addLength                           ; $723E
.tableLength
    push hl                                 ; $7240
    ld a,[wSndTrackIndex]                   ; $7241
    cp $04                                  ; $7244
    jr nc,.l7251                            ; $7246
    ld a,[wSndMusicLengths]                 ; $7248
    ld l,a                                  ; $724B
    ld a,[wSndMusicLengths + 1]             ; $724C
    jr .l7258                               ; $724F
.l7251
    ld a,[wSndSfxLengths]                   ; $7251
    ld l,a                                  ; $7254
    ld a,[wSndSfxLengths + 1]               ; $7255
.l7258
    ld h,a                                  ; $7258
    ld a,[de]                               ; $7259
    and $F0                                 ; $725A
    srl a                                   ; $725C
    srl a                                   ; $725E
    srl a                                   ; $7260
    add a,l                                 ; $7262
    ld l,a                                  ; $7263
    jr nc,.l7267                            ; $7264
    inc h                                   ; $7266
.l7267
    ld a,[hli]                              ; $7267
    ld c,a                                  ; $7268
    ld a,[hl]                               ; $7269
    ld b,a                                  ; $726A
    pop hl                                  ; $726B
; counter += length * 8
.addLength
    sla c                                   ; $726C
    rl b                                    ; $726E
    sla c                                   ; $7270
    rl b                                    ; $7272
    sla c                                   ; $7274
    rl b                                    ; $7276
    dec l                                   ; $7278
    dec l                                   ; $7279
    ld a,[hl]                               ; $727A
    add a,c                                 ; $727B
    ld [hli],a                              ; $727C
    ld a,[hl]                               ; $727D
    adc a,b                                 ; $727E
    ld [hli],a                              ; $727F
    ; lo nibble: 9 = tie (keep sounding, status unchanged), 8 = rest,
    ; 6 = absolute note in the next byte, 0-5/7 = note + n, A-F = note - (16-n).
    ld a,[wSndRowByte]                      ; $7280
    and $0F                                 ; $7283
    cp $09                                  ; $7285
    jr nz,.notTie                           ; $7287
    inc de                                  ; $7289
    pop hl                                  ; $728A
    inc hl                                  ; $728B
    jp .savePtr                             ; $728C  tie: only the pointer is saved
.notTie
    cp $08                                  ; $728F
    jr z,.rest                              ; $7291
    cp $06                                  ; $7293
    jr nz,.relative                         ; $7295
    inc de                                  ; $7297
    ld a,[de]                               ; $7298
    jr .setNote                             ; $7299
.relative
    cp $08                                  ; $729B
    jr c,.l72A1                             ; $729D
    or $F0                                  ; $729F
.l72A1
    add a,[hl]                              ; $72A1
.setNote
    ld [hli],a                              ; $72A2
    ld b,a                                  ; $72A3
    ld a,[wSndTrackIndex]                   ; $72A4
    cp $03                                  ; $72A7
    jr z,.drumMusic                         ; $72A9
    cp $05                                  ; $72AB
    jr z,.drumSfx                           ; $72AD
; tone channels: frequency = FreqTable[note - $10]. Only the low 3 bits
; of TRK_NR4 are replaced, so the instrument keeps its trigger/length bits.
.toneNote
    ld a,b                                  ; $72AF
    sla a                                   ; $72B0
    ld bc,FreqTable - $20                   ; $72B2
    add a,c                                 ; $72B5
    ld c,a                                  ; $72B6
    ld a,b                                  ; $72B7
    adc a,$00                               ; $72B8
    ld b,a                                  ; $72BA
    inc l                                   ; $72BB
    inc l                                   ; $72BC
    inc l                                   ; $72BD
    ld a,[bc]                               ; $72BE
    ld [hli],a                              ; $72BF
    inc bc                                  ; $72C0
    ld a,[bc]                               ; $72C1
    and $07                                 ; $72C2
    ld b,a                                  ; $72C4
    ld a,[hl]                               ; $72C5
    and $F8                                 ; $72C6
    or b                                    ; $72C8
    ld [hli],a                              ; $72C9
    ; note start for the instrument mode
    ld a,[hli]                              ; $72CA
    and a                                   ; $72CB
    jp z,.keyOn                             ; $72CC
    cp $02                                  ; $72CF
    jr nc,.notMode1                         ; $72D1
    ; mode 1: restart the step counter and load step 0 as NRx2 volume
    ld a,[hli]                              ; $72D3
    ld [hli],a                              ; $72D4
    push de                                 ; $72D5
    ld a,[hli]                              ; $72D6
    ld e,a                                  ; $72D7
    ld a,[hli]                              ; $72D8
    ld d,a                                  ; $72D9
    ld a,[de]                               ; $72DA
    ld b,a                                  ; $72DB
    ld a,$00                                ; $72DC
    ld [hl],a                               ; $72DE
    ld a,l                                  ; $72DF
    sub $08                                 ; $72E0
    ld l,a                                  ; $72E2
    ld a,[hl]                               ; $72E3
    and $0F                                 ; $72E4
    swap b                                  ; $72E6
    or b                                    ; $72E8
    ld [hl],a                               ; $72E9
    pop de                                  ; $72EA
    jp .keyOn                               ; $72EB
.notMode1
    jr nz,.gate                             ; $72EE
    ld a,[hli]                              ; $72F0
    ld [hli],a                              ; $72F1
    jp .keyOn                               ; $72F2
; mode 3: TRK_ENVPTR (used as a word here) = counter - gate.
.gate
    push hl                                 ; $72F5
    ld a,l                                  ; $72F6
    sub $09                                 ; $72F7
    ld l,a                                  ; $72F9
    ld a,[hli]                              ; $72FA
    ld c,a                                  ; $72FB
    ld a,[hl]                               ; $72FC
    ld b,a                                  ; $72FD
    pop hl                                  ; $72FE
    ld a,c                                  ; $72FF
    sub [hl]                                ; $7300
    ld c,a                                  ; $7301
    inc l                                   ; $7302
    ld a,b                                  ; $7303
    sbc a,[hl]                              ; $7304
    ld b,a                                  ; $7305
    inc l                                   ; $7306
    ld a,c                                  ; $7307
    ld [hli],a                              ; $7308
    ld a,b                                  ; $7309
    ld [hl],a                               ; $730A
    jp .keyOn                               ; $730B
; rest: status 5 = release
.rest
    ld a,$05                                ; $730E
    jp .setStatus                           ; $7310
; noise tracks: NR41-NR44 from DrumTable[note - $34]
.drumMusic
    ld hl,DrumTable                         ; $7313
    ld a,b                                  ; $7316
    sub $34                                 ; $7317
    sla a                                   ; $7319
    sla a                                   ; $731B
    add a,l                                 ; $731D
    ld l,a                                  ; $731E
    jr nc,.l7322                            ; $731F
    inc h                                   ; $7321
.l7322
    ld bc,wSndCh4 + TRK_NR1                 ; $7322
    jr .copyDrum                            ; $7325
.drumSfx
    ld hl,DrumTable                         ; $7327
    ld a,b                                  ; $732A
    sub $34                                 ; $732B
    sla a                                   ; $732D
    sla a                                   ; $732F
    add a,l                                 ; $7331
    ld l,a                                  ; $7332
    jr nc,.l7336                            ; $7333
    inc h                                   ; $7335
.l7336
    ld bc,wSndSfxCh4 + TRK_NR1              ; $7336
.copyDrum
    ld a,[hli]                              ; $7339
    ld [bc],a                               ; $733A
    inc bc                                  ; $733B
    ld a,[hli]                              ; $733C
    ld [bc],a                               ; $733D
    inc bc                                  ; $733E
    ld a,[hli]                              ; $733F
    ld [bc],a                               ; $7340
    inc bc                                  ; $7341
    ld a,[hli]                              ; $7342
    ld [bc],a                               ; $7343
; status 6 = key on (full register write in SndOutput)
.keyOn
    ld a,$06                                ; $7344
.setStatus
    inc de                                  ; $7346
    pop hl                                  ; $7347
    ld [hli],a                              ; $7348
.savePtr
    ld a,e                                  ; $7349
    ld [hli],a                              ; $734A
    ld a,d                                  ; $734B
    ld [hli],a                              ; $734C
    ld a,[wSndTrackIndex]                   ; $734D
    cp $05                                  ; $7350
    ret nc                                  ; $7352
    inc a                                   ; $7353
    ld [wSndTrackIndex],a                   ; $7354
    ld a,l                                  ; $7357
    add a,$1D                               ; $7358
    ld l,a                                  ; $735A
    jp SndTrackLoop                         ; $735B

; Commands $E0-$FF
SndParseCmd:
    cp $FE                                  ; $735E
    jp c,.notEnd                            ; $7360
    jr z,.restart                           ; $7363
    pop hl                                  ; $7365  $FF: end of track
    ld a,$04                                ; $7366
    ld [hl],a                               ; $7368
    jp SndNextTrack.noPop                   ; $7369
; $FE: restart the track from its first byte (TRK_START), loop depth 0
.restart
    push hl                                 ; $736C
    ld a,$19                                ; $736D
    add a,l                                 ; $736F
    ld l,a                                  ; $7370
    ld a,[hli]                              ; $7371
    ld e,a                                  ; $7372
    ld a,[hl]                               ; $7373
    ld d,a                                  ; $7374
    ld a,$F2                                ; $7375
    add a,l                                 ; $7377
    ld l,a                                  ; $7378
    ld a,$00                                ; $7379
    ld [hl],a                               ; $737B
    pop hl                                  ; $737C
    jp SndParse                             ; $737D
; $E0 n: loop start. Pushes a 4-byte frame (pass = 1, n, return address).
.notEnd
    cp $E0                                  ; $7380
    jp nz,.notLoopStart                     ; $7382
    push hl                                 ; $7385
    ld a,l                                  ; $7386
    add a,$0C                               ; $7387
    ld l,a                                  ; $7389
    ld a,[hl]                               ; $738A
    inc a                                   ; $738B
    ld [hli],a                              ; $738C
    dec a                                   ; $738D
    sla a                                   ; $738E
    sla a                                   ; $7390
    add a,l                                 ; $7392
    ld l,a                                  ; $7393
    ld a,$01                                ; $7394
    ld [hli],a                              ; $7396
    inc de                                  ; $7397
    ld a,[de]                               ; $7398
    ld [hli],a                              ; $7399
    inc de                                  ; $739A
    ld a,e                                  ; $739B
    ld [hli],a                              ; $739C
    ld a,d                                  ; $739D
    ld [hli],a                              ; $739E
    pop hl                                  ; $739F
    jp SndParse                             ; $73A0
; $E1: loop end. pass += 1; repeat while pass <= n.
.notLoopStart
    cp $E1                                  ; $73A3
    jp nz,.notLoopEnd                       ; $73A5
    push hl                                 ; $73A8
    ld a,l                                  ; $73A9
    add a,$0C                               ; $73AA
    ld l,a                                  ; $73AC
    ld a,[hli]                              ; $73AD
    dec a                                   ; $73AE
    sla a                                   ; $73AF
    sla a                                   ; $73B1
    add a,l                                 ; $73B3
    ld l,a                                  ; $73B4
    inc [hl]                                ; $73B5
    ld a,[hli]                              ; $73B6
    ld b,a                                  ; $73B7
    ld a,[hli]                              ; $73B8
    sub b                                   ; $73B9
    jr c,.exitLoop                          ; $73BA
    ld a,[hli]                              ; $73BC
    ld e,a                                  ; $73BD
    ld a,[hl]                               ; $73BE
    ld d,a                                  ; $73BF
    pop hl                                  ; $73C0
    jp SndParse                             ; $73C1
.exitLoop
    inc de                                  ; $73C4
.popLoop
    pop hl                                  ; $73C5
    push hl                                 ; $73C6
    ld a,l                                  ; $73C7
    add a,$0C                               ; $73C8
    ld l,a                                  ; $73CA
    dec [hl]                                ; $73CB
    pop hl                                  ; $73CC
    jp SndParse                             ; $73CD
; $E2 p: pass marker (alternate ending). Scans forward from the $E2
; itself to the first "$E2 p" whose p equals the current pass, and
; continues after it. If that pass is the last one, the loop frame is
; dropped (the last ending has no $E1).
.notLoopEnd
    cp $E2                                  ; $73D0
    jp nz,.pan                              ; $73D2
    push hl                                 ; $73D5
    ld a,l                                  ; $73D6
    add a,$0C                               ; $73D7
    ld l,a                                  ; $73D9
    ld a,[hli]                              ; $73DA
    dec a                                   ; $73DB
    sla a                                   ; $73DC
    sla a                                   ; $73DE
    add a,l                                 ; $73E0
    ld l,a                                  ; $73E1
    ld a,[hli]                              ; $73E2
    ld b,a                                  ; $73E3
    ld a,[hl]                               ; $73E4
    ld c,a                                  ; $73E5
.scan
    ld a,[de]                               ; $73E6
    inc de                                  ; $73E7
    cp $E2                                  ; $73E8
    jr nz,.scanNotPass                      ; $73EA
    ld a,[de]                               ; $73EC
    inc de                                  ; $73ED
    cp b                                    ; $73EE
    jr z,.found                             ; $73EF
    jr .scan                                ; $73F1
.scanNotPass
    cp $E0                                  ; $73F3
    jr c,.scanRow                           ; $73F5
    cp $E1                                  ; $73F7
    jr z,.scan                              ; $73F9
    inc de                                  ; $73FB
    jr .scan                                ; $73FC
.scanRow
    cp $D0                                  ; $73FE
    jr c,.scanNoteByte                      ; $7400
    inc de                                  ; $7402
    inc de                                  ; $7403
.scanNoteByte
    and $0F                                 ; $7404
    cp $06                                  ; $7406
    jr nz,.scan                             ; $7408
    inc de                                  ; $740A
    jr .scan                                ; $740B
.found
    ld a,b                                  ; $740D
    cp c                                    ; $740E
    jr z,.popLoop                           ; $740F
    pop hl                                  ; $7411
    jp SndParse                             ; $7412
; any other command ($E3-$EF, $F1-$FD) xx: NR51 = xx (global pan),
; written by the next SndOutput.
.pan
    inc de                                  ; $7415
    ld a,[de]                               ; $7416
    inc de                                  ; $7417
    ld [wSndPan],a                          ; $7418
    ld a,$01                                ; $741B
    ld [wSndPanFlag],a                      ; $741D
    jp SndParse                             ; $7420

; No new row this tick: run the instrument envelope (only while a
; note is sounding, status 2).
SndTrackEnvelope:
    ld a,c                                  ; $7423
    cp $02                                  ; $7424
    jp nz,SndNextTrack                      ; $7426
    ld a,l                                  ; $7429
    add a,$06                               ; $742A
    ld l,a                                  ; $742C
    ld a,[hli]                              ; $742D
    and a                                   ; $742E
    jp z,SndNextTrack                       ; $742F
    cp $01                                  ; $7432
    jp nz,.notVolSteps                      ; $7434
    ; mode 1: every TRK_ENVPARAM frames, the next volume step goes to the
    ; NRx2 high nibble and the note is retriggered (status 6).
    inc l                                   ; $7437
    ld a,[hl]                               ; $7438
    dec a                                   ; $7439
    ld [hld],a                              ; $743A
    jp nz,SndNextTrack                      ; $743B
    ld a,[hli]                              ; $743E
    ld [hli],a                              ; $743F
    ld a,[hli]                              ; $7440
    ld e,a                                  ; $7441
    ld a,[hli]                              ; $7442
    ld d,a                                  ; $7443
    ld a,[hl]                               ; $7444
    add a,e                                 ; $7445
    ld e,a                                  ; $7446
    jr nc,.l744A                            ; $7447
    inc d                                   ; $7449
.l744A
    ld a,[hl]                               ; $744A
    cp $03                                  ; $744B
    jr nc,.l7450                            ; $744D
    inc [hl]                                ; $744F
.l7450
    ld a,[de]                               ; $7450
    ld b,a                                  ; $7451
    ld a,l                                  ; $7452
    sub $08                                 ; $7453
    ld l,a                                  ; $7455
    ld a,[hl]                               ; $7456
    and $0F                                 ; $7457
    swap b                                  ; $7459
    or b                                    ; $745B
    ld [hl],a                               ; $745C
    jp .retrigger                           ; $745D
; mode 2: decrements the counter, but "dec" leaves carry clear after the
; "cp $02", so "jp nc" is always taken and the note is never released.
.notVolSteps
    cp $02                                  ; $7460
    jr nz,.gateCount                        ; $7462
    inc l                                   ; $7464
    ld a,[hl]                               ; $7465
    dec a                                   ; $7466
    ld [hld],a                              ; $7467
    jp nc,SndNextTrack                      ; $7468
    ld a,$05                                ; $746B
    jr .store                               ; $746D
; mode 3: gate countdown -= tempo; on underflow, release (status 5).
; This cuts the note about n frames before its row ends.
.gateCount
    inc l                                   ; $746F
    inc l                                   ; $7470
    ld a,[wSndTrackIndex]                   ; $7471
    cp $04                                  ; $7474
    jr nc,.l747D                            ; $7476
    ld a,[wSndMusicTempo]                   ; $7478
    jr .l7480                               ; $747B
.l747D
    ld a,[wSndSfxTempo]                     ; $747D
.l7480
    ld b,a                                  ; $7480
    ld a,[hl]                               ; $7481
    sub b                                   ; $7482
    ld [hli],a                              ; $7483
    ld a,[hl]                               ; $7484
    sbc a,$00                               ; $7485
    ld [hl],a                               ; $7487
    jr nc,SndNextTrack                      ; $7488
    ld a,$05                                ; $748A
    jr .store                               ; $748C
.retrigger
    ld a,$06                                ; $748E
.store
    pop hl                                  ; $7490
    ld [hl],a                               ; $7491
    ld a,[wSndTrackIndex]                   ; $7492
    cp $05                                  ; $7495
    ret nc                                  ; $7497
    inc a                                   ; $7498
    ld [wSndTrackIndex],a                   ; $7499
    ld a,l                                  ; $749C
    add a,$20                               ; $749D
    ld l,a                                  ; $749F
    jp SndTrackLoop                         ; $74A0
SndNextTrack:
    pop hl                                  ; $74A3
.noPop
    ld a,[wSndTrackIndex]                   ; $74A4
    cp $05                                  ; $74A7
    ret nc                                  ; $74A9
    inc a                                   ; $74AA
    ld [wSndTrackIndex],a                   ; $74AB
    ld a,l                                  ; $74AE
    add a,$20                               ; $74AF
    ld l,a                                  ; $74B1
    jp SndTrackLoop                         ; $74B2

; SndOutput: writes the registers decided by the last SndUpdate.
; Status after SndUpdate: 6 = key on, 5 = release, 4 = ending.
; Each is reduced by 4 here (2 = sounding, 1 = released, 0 = off).
SndOutput:
    ld a,[wSndSfxTracks]                    ; $74B5
    and a                                   ; $74B8
    jp nz,SndOutputWithSfx                  ; $74B9
    ld a,[wSndPanFlag]                      ; $74BC
    cp $01                                  ; $74BF
    jr nz,.ch1                              ; $74C1
    ld a,$00                                ; $74C3
    ld [wSndPanFlag],a                      ; $74C5
    ld a,[wSndPan]                          ; $74C8
    ldh [rNR51],a                           ; $74CB
.ch1
    ld a,[wSndCh1]                          ; $74CD
    sub $04                                 ; $74D0
    jr c,.ch2                               ; $74D2
    ld [wSndCh1],a                          ; $74D4
    cp $02                                  ; $74D7
    jr z,.ch1Write                          ; $74D9
    cp $01                                  ; $74DB
    jr z,.ch1Release                        ; $74DD
    ; ending: silence the channel, one track fewer; at 0 the song is over
    ld a,$08                                ; $74DF
    ldh [rNR12],a                           ; $74E1
    ld a,$80                                ; $74E3
    ldh [rNR14],a                           ; $74E5
    ld a,[wSndMusicTracks]                  ; $74E7
    dec a                                   ; $74EA
    ld [wSndMusicTracks],a                  ; $74EB
    jr nz,.ch2                              ; $74EE
    ld a,$FF                                ; $74F0
    ld [wSndMusicId],a                      ; $74F2
    jr .ch2                                 ; $74F5
; release: NRx2 keeps only its low nibble (volume 0) + retrigger
.ch1Release
    ld a,[wSndCh1 + TRK_NR2]                ; $74F7
    and $0F                                 ; $74FA
    ldh [rNR12],a                           ; $74FC
    ld a,[wSndCh1 + TRK_NR4]                ; $74FE
    ldh [rNR14],a                           ; $7501
    jr .ch2                                 ; $7503
.ch1Write
    ld hl,wSndCh1 + TRK_NR0                 ; $7505
    ld c,$10                                ; $7508
    ld a,[hli]                              ; $750A
    ldh [c],a                               ; $750B
    inc c                                   ; $750C
    ld a,[hli]                              ; $750D
    ldh [c],a                               ; $750E
    inc c                                   ; $750F
    ld a,[hli]                              ; $7510
    ldh [c],a                               ; $7511
    inc c                                   ; $7512
    ld a,[hli]                              ; $7513
    ldh [c],a                               ; $7514
    inc c                                   ; $7515
    ld a,[hl]                               ; $7516
    ldh [c],a                               ; $7517
.ch2
    ld a,[wSndCh2]                          ; $7518
    sub $04                                 ; $751B
    jr c,.ch3                               ; $751D
    ld [wSndCh2],a                          ; $751F
    cp $02                                  ; $7522
    jr z,.ch2Write                          ; $7524
    cp $01                                  ; $7526
    jr z,.ch2Release                        ; $7528
    ld a,$08                                ; $752A
    ldh [rNR22],a                           ; $752C
    ld a,$80                                ; $752E
    ldh [rNR24],a                           ; $7530
    ld a,[wSndMusicTracks]                  ; $7532
    dec a                                   ; $7535
    ld [wSndMusicTracks],a                  ; $7536
    jr nz,.ch3                              ; $7539
    ld a,$FF                                ; $753B
    ld [wSndMusicId],a                      ; $753D
    jr .ch3                                 ; $7540
.ch2Release
    ld a,[wSndCh2 + TRK_NR2]                ; $7542
    and $0F                                 ; $7545
    ldh [rNR22],a                           ; $7547
    ld a,[wSndCh2 + TRK_NR4]                ; $7549
    ldh [rNR24],a                           ; $754C
    jr .ch3                                 ; $754E
.ch2Write
    ld hl,wSndCh2 + TRK_NR1                 ; $7550
    ld c,$16                                ; $7553
    ld a,[hli]                              ; $7555
    ldh [c],a                               ; $7556
    inc c                                   ; $7557
    ld a,[hli]                              ; $7558
    ldh [c],a                               ; $7559
    inc c                                   ; $755A
    ld a,[hli]                              ; $755B
    ldh [c],a                               ; $755C
    inc c                                   ; $755D
    ld a,[hl]                               ; $755E
    ldh [c],a                               ; $755F
.ch3
    ld a,[wSndCh3]                          ; $7560
    sub $04                                 ; $7563
    jr c,.ch4                               ; $7565
    ld [wSndCh3],a                          ; $7567
    cp $02                                  ; $756A
    jr z,.ch3Write                          ; $756C
    cp $01                                  ; $756E
    jr z,.ch3Release                        ; $7570
    ld a,$00                                ; $7572
    ldh [rNR30],a                           ; $7574
    ld a,[wSndMusicTracks]                  ; $7576
    dec a                                   ; $7579
    ld [wSndMusicTracks],a                  ; $757A
    jr nz,.ch4                              ; $757D
    ld a,$FF                                ; $757F
    ld [wSndMusicId],a                      ; $7581
    jr .ch4                                 ; $7584
.ch3Release
    ld a,$00                                ; $7586
    ldh [rNR30],a                           ; $7588
    jr .ch4                                 ; $758A
; ch3 key on: if ch3 is already running only the frequency is updated
; (no retrigger). Otherwise NR31-NR34 are written with NR30 = $80.
.ch3Write
    ldh a,[rNR52]                           ; $758C
    and $04                                 ; $758E
    jr nz,.ch3Legato                        ; $7590
    ld hl,wSndCh3 + TRK_NR1                 ; $7592
    ld c,$1B                                ; $7595
    ld a,[hli]                              ; $7597
    ldh [c],a                               ; $7598
    inc c                                   ; $7599
    ld a,[hli]                              ; $759A
    ldh [c],a                               ; $759B
    inc c                                   ; $759C
    ld a,[hli]                              ; $759D
    ldh [c],a                               ; $759E
    inc c                                   ; $759F
    ld a,$80                                ; $75A0
    ldh [rNR30],a                           ; $75A2
    ld a,[hl]                               ; $75A4
    ldh [c],a                               ; $75A5
    jr .ch4                                 ; $75A6
.ch3Legato
    ld a,[wSndCh3 + TRK_NR3]                ; $75A8
    ldh [rNR33],a                           ; $75AB
    ld a,[wSndCh3 + TRK_NR4]                ; $75AD
    and $7F                                 ; $75B0
    ldh [rNR34],a                           ; $75B2
.ch4
    ld a,[wSndCh4]                          ; $75B4
    sub $04                                 ; $75B7
    ret c                                   ; $75B9
    ld [wSndCh4],a                          ; $75BA
    cp $02                                  ; $75BD
    jr z,.ch4Write                          ; $75BF
    cp $01                                  ; $75C1
    jr z,.ch4Release                        ; $75C3
    ld a,$08                                ; $75C5
    ldh [rNR42],a                           ; $75C7
    ld a,$80                                ; $75C9
    ldh [rNR44],a                           ; $75CB
    ld a,[wSndMusicTracks]                  ; $75CD
    dec a                                   ; $75D0
    ld [wSndMusicTracks],a                  ; $75D1
    ret nz                                  ; $75D4
    ld a,$FF                                ; $75D5
    ld [wSndMusicId],a                      ; $75D7
    ret                                     ; $75DA
.ch4Release
    ld a,[wSndCh4 + TRK_NR2]                ; $75DB
    and $0F                                 ; $75DE
    ldh [rNR42],a                           ; $75E0
    ld a,[wSndCh4 + TRK_NR4]                ; $75E2
    ldh [rNR44],a                           ; $75E5
    ret                                     ; $75E7
.ch4Write
    ld hl,wSndCh4 + TRK_NR1                 ; $75E8
    ld c,$20                                ; $75EB
    ld a,[hli]                              ; $75ED
    ldh [c],a                               ; $75EE
    inc c                                   ; $75EF
    ld a,[hli]                              ; $75F0
    ldh [c],a                               ; $75F1
    inc c                                   ; $75F2
    ld a,[hli]                              ; $75F3
    ldh [c],a                               ; $75F4
    inc c                                   ; $75F5
    ld a,[hl]                               ; $75F6
    ldh [c],a                               ; $75F7
    ret                                     ; $75F8

; Same as SndOutput while an SFX runs. Music ch1/ch4 are held at
; status 1 (parsed but not written); hardware ch1/ch4 play the SFX.
; On the first frame NR51 gets $99 ORed in so ch1/ch4 are audible.
SndOutputWithSfx:
    ld a,[wSndPanFlag]                      ; $75F9
    cp $01                                  ; $75FC
    jr nz,.musCh1                           ; $75FE
    ld a,$00                                ; $7600
    ld [wSndPanFlag],a                      ; $7602
    ld a,[wSndPan]                          ; $7605
    or $99                                  ; $7608
    ldh [rNR51],a                           ; $760A
.musCh1
    ld a,[wSndCh1]                          ; $760C
    cp $04                                  ; $760F
    jr z,.musCh1End                         ; $7611
    and a                                   ; $7613
    jr z,.sfxCh1                            ; $7614
    ld a,$01                                ; $7616
    ld [wSndCh1],a                          ; $7618
    jr .sfxCh1                              ; $761B
.musCh1End
    xor a                                   ; $761D
    ld [wSndCh1],a                          ; $761E
    ld a,[wSndMusicTracks]                  ; $7621
    dec a                                   ; $7624
    ld [wSndMusicTracks],a                  ; $7625
    jr nz,.sfxCh1                           ; $7628
    ld a,$FF                                ; $762A
    ld [wSndMusicId],a                      ; $762C
.sfxCh1
    ld a,[wSndSfxCh1]                       ; $762F
    sub $04                                 ; $7632
    jr c,.ch2                               ; $7634
    ld [wSndSfxCh1],a                       ; $7636
    cp $02                                  ; $7639
    jr z,.sfxCh1Write                       ; $763B
    cp $01                                  ; $763D
    jr z,.sfxCh1Release                     ; $763F
    ld a,$08                                ; $7641
    ldh [rNR12],a                           ; $7643
    ld a,$80                                ; $7645
    ldh [rNR14],a                           ; $7647
    ld a,[wSndSfxTracks]                    ; $7649
    dec a                                   ; $764C
    ld [wSndSfxTracks],a                    ; $764D
    jr nz,.ch2                              ; $7650
    ; SFX over: restore the music NR51 on the next SndOutput
    ld a,$01                                ; $7652
    ld [wSndPanFlag],a                      ; $7654
    ld a,$FF                                ; $7657
    ld [wSndSfxId],a                        ; $7659
    jr .ch2                                 ; $765C
.sfxCh1Release
    ld a,[wSndSfxCh1 + TRK_NR2]             ; $765E
    and $0F                                 ; $7661
    ldh [rNR12],a                           ; $7663
    ld a,[wSndSfxCh1 + TRK_NR4]             ; $7665
    ldh [rNR14],a                           ; $7668
    jr .ch2                                 ; $766A
.sfxCh1Write
    ld hl,wSndSfxCh1 + TRK_NR0              ; $766C
    ld c,$10                                ; $766F
    ld a,[hli]                              ; $7671
